<?php

declare(strict_types=1);
require __DIR__ . '/config/bootstrap.php';
$topicId = communityPositiveInt($_GET['id'] ?? null) ?? 0;
$topic = $topicId ? loadDiscussionTopic(db(), $topicId) : null;
if (!$topic) { renderErrorPage(404, 'Discussion not found', 'This discussion is unavailable, hidden or deleted.'); }
$page = communityPositiveInt($_GET['page'] ?? 1) ?? 1;
$replies = loadDiscussionReplies(db(), $topicId, $page);
$viewerId = isAuthenticated() ? (int) currentUser()['id'] : null;
$pageTitle = $topic['title'];
require SKADI_ROOT . '/includes/header.php';
?>
<section class="community-page"><nav class="breadcrumb-nav"><ol class="breadcrumb"><li class="breadcrumb-item"><a href="<?= escape(baseUrl('discussions.php?game=' . (int) $topic['game_id'])) ?>">Discussions</a></li><li class="breadcrumb-item active"><?= escape($topic['title']) ?></li></ol></nav><article class="topic-card"><header><div><p class="eyebrow"><?= escape($topic['game_title']) ?> · <?= escape($topic['category_name']) ?></p><h1><?= escape($topic['title']) ?></h1><p>By <a href="<?= escape(baseUrl('profile.php?id=' . rawurlencode($topic['skadi_id']))) ?>"><?= escape($topic['display_name']) ?></a></p></div><?php if ($topic['is_locked']): ?><span class="badge text-bg-secondary">Locked</span><?php endif; ?></header><p><?= nl2br(escape($topic['body'])) ?></p><?php if ($viewerId === (int) $topic['author_user_id']): ?><a class="btn btn-sm btn-outline-secondary" href="<?= escape(baseUrl('topic-edit.php?id=' . $topicId)) ?>">Edit topic</a><?php endif; ?><?php renderReportForm('topic', $topicId, 'discussion.php?id=' . $topicId); ?></article>
<section class="reply-list"><h2>Replies</h2><?php if ($replies['items'] === []): ?><p>No replies yet.</p><?php endif; ?><?php foreach ($replies['items'] as $reply): ?><article class="reply-card" id="reply-<?= (int) $reply['id'] ?>"><header><a href="<?= escape(baseUrl('profile.php?id=' . rawurlencode($reply['skadi_id']))) ?>"><?= escape($reply['display_name']) ?></a><small><?= escape($reply['created_at']) ?><?= $reply['updated_at'] !== $reply['created_at'] ? ' · edited' : '' ?></small></header><p><?= nl2br(escape($reply['body'])) ?></p><?php if ($viewerId === (int) $reply['author_user_id']): ?><details><summary>Edit reply</summary><form method="post" action="<?= escape(baseUrl('actions/reply-save.php')) ?>"><?= csrfInput() ?><input type="hidden" name="reply_id" value="<?= (int) $reply['id'] ?>"><textarea class="form-control" name="body" maxlength="10000" required><?= escape($reply['body']) ?></textarea><button class="btn btn-sm btn-primary" type="submit">Save</button></form></details><?php endif; ?><?php renderReportForm('reply', (int) $reply['id'], 'discussion.php?id=' . $topicId . '#reply-' . (int) $reply['id']); ?></article><?php endforeach; ?></section>
<nav class="catalog-pagination"><?php if ($replies['page'] > 1): ?><a href="?id=<?= $topicId ?>&page=<?= $replies['page'] - 1 ?>">Previous</a><?php endif; ?><span>Page <?= $replies['page'] ?> of <?= $replies['pages'] ?></span><?php if ($replies['page'] < $replies['pages']): ?><a href="?id=<?= $topicId ?>&page=<?= $replies['page'] + 1 ?>">Next</a><?php endif; ?></nav><?php if ($viewerId !== null && !$topic['is_locked']): ?><form class="reply-form" method="post" action="<?= escape(baseUrl('actions/reply-add.php')) ?>"><?= csrfInput() ?><input type="hidden" name="topic_id" value="<?= $topicId ?>"><label>Add reply<textarea class="form-control" name="body" maxlength="10000" rows="5" required></textarea></label><button class="btn btn-primary" type="submit">Reply</button></form><?php elseif ($topic['is_locked']): ?><p class="privacy-notice">This topic is locked. New replies are rejected by the server.</p><?php else: ?><p><a href="<?= escape(baseUrl('login.php')) ?>">Sign in</a> to reply.</p><?php endif; ?></section>
<?php require SKADI_ROOT . '/includes/footer.php'; ?>
